48	 /* lanes: [{ off (m từ tim cầu), n, speed, bike (tỉ lệ xe máy), bus (tỉ lệ xe buýt) }] — mỗi làn chạy cả hai chiều; name: tên InstancedMesh của hệ xe */
49	 export function createTraffic(bridge: { life: THREE.Group }, { seed, x0, x1, lanes, name }: { seed: number; x0: number; x1: number; lanes: LaneSpec[]; name: string }): Traffic {
50	   const rnd = rng(seed), list: BridgeVehicle[] = [], V = CONFIG.vehicles, colors = V.carColors;
51	   for (const dir of [1, -1]) lanes.forEach(({ off, n, speed, bike = 0, bus = 0.08 }) => {
52	     for (let k = 0; k < n; k++) {
53	       const r = rnd(), type: VehicleType = r < bike ? 'bike' : r < bus ? 'bus' : 'car';
54	       list.push({ lane: off, dir, type, s: x0 + (k + rnd() * 0.6) * (x1 - x0) / n, speed: speed * (0.85 + rnd() * 0.3),
55	         color: type === 'bike' ? V.bikeColors[k % V.bikeColors.length] : type === 'bus' ? V.palette.busBody : colors[Math.floor(rnd() * colors.length)] });
56	     }
57	   });
58	   const T: Traffic = { list, x0, x1, fleet: vhCreateFleet(list.length, bridge.life, name) };   // 1 InstancedMesh = 1 lệnh vẽ cho cả hệ
