85	function drHitBox(b: DrBox, x: number, y: number, z: number, c: number, s: number): boolean {
86	  if (Math.abs(b.y - y) >= CAR.height) return false;
87	  const bc = Math.cos(b.yaw), bs = Math.sin(b.yaw), dx = b.x - x, dz = b.z - z;
88	  /* bốn trục tách: f1 = (c, −s), n1 = (s, c), f2 = (bc, −bs), n2 = (bs, bc); hình chiếu nửa hộp lên trục a là hl|f·a| + hw|n·a| */
89	  const ff = c * bc + s * bs, fn = c * bs - s * bc;                  // f1·f2, f1·n2
90	  const nf = s * bc - c * bs, nn = s * bs + c * bc;                  // n1·f2, n1·n2
91	  if (Math.abs(dx * c - dz * s) >= HL + b.hl * Math.abs(ff) + b.hw * Math.abs(fn) - EPS) return false;
92	  if (Math.abs(dx * s + dz * c) >= HW + b.hl * Math.abs(nf) + b.hw * Math.abs(nn) - EPS) return false;
93	  if (Math.abs(dx * bc - dz * bs) >= b.hl + HL * Math.abs(ff) + HW * Math.abs(nf) - EPS) return false;
94	  if (Math.abs(dx * bs + dz * bc) >= b.hw + HL * Math.abs(fn) + HW * Math.abs(nn) - EPS) return false;
95	  return true;
96	}
97	
98	/* ===== Thân xe hợp lệ ===== */
99	export function drFits(net: DrNet, p: DrPose, boxes: DrBox[], nBoxes: number, ignore: Uint8Array): boolean {
100	  const yRef = p.y, c = Math.cos(p.yaw), s = Math.sin(p.yaw);
101	  for (let i = -1; i <= 1; i++) for (let j = -1; j <= 1; j++) {
102	    const lf = i * HL, ln = j * HW;
103	    if (Number.isNaN(drGround(net, p.x + lf * c + ln * s, p.z - lf * s + ln * c, yRef))) return false;
104	  }
105	  const ya = yRef + SIM.floor, yb = yRef + CAR.height, sol = net.solids, g = drGrid(net);
106	  const big = g.big;
107	  for (let i = 0; i < big.length; i++) { const o = sol[big[i]]; if (o.y1 > ya && o.y0 < yb && drHitSolid(o, p.x, p.z, c, s)) return false; }
108	  const R = HL * Math.abs(c) + HW * Math.abs(s), Rz = HL * Math.abs(s) + HW * Math.abs(c);   // nửa khung bao thân xe theo X, Z
109	  const ix0 = Math.floor((p.x - R) / DRC), ix1 = Math.floor((p.x + R) / DRC), iz0 = Math.floor((p.z - Rz) / DRC), iz1 = Math.floor((p.z + Rz) / DRC);
110	  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
111	    const list = g.cells.get(drKey(ix, iz));
112	    if (!list) continue;
113	    for (let i = 0; i < list.length; i++) { const o = sol[list[i]]; if (o.y1 > ya && o.y0 < yb && drHitSolid(o, p.x, p.z, c, s)) return false; }
114	  }
115	  for (let i = 0; i < nBoxes; i++) if (!ignore[i] && drHitBox(boxes[i], p.x, yRef, p.z, c, s)) return false;
116	  return true;
117	}
118	
119	/* ===== Đường thoát ===== */
120	/* Mức "tệ" của tư thế p không hợp lệ, ghi vào BAD_N, BAD_D:
121	   BAD_N = số điểm mẫu (trong 9) không có mặt đường cùng tầng; BAD_D = tổng độ lấn (drPenSolid > 0) vào các vật cản tĩnh cùng khoảng cao độ.
